Path('src/app/coach-hub-view.module.css').write_text(r'''.layout{display:grid;gap:16px;color:#25313c}.tabs{display:flex;gap:8px;flex-wrap:wrap}.tabs button{border:1px solid #dbe3ea;background:#fff;border-radius:9px;padding:9px 13px;font-weight:800;color:#334155;cursor:pointer}.tabs .active{background:#111827;color:#fff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:14px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px;box-shadow:0 8px 24px rgba(15,23,42,.05)}.card h3{margin:0 0 6px;font-size:15px}.card p{margin:5px 0;color:#64748b;line-height:1.45}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.kpi{background:#0f172a;color:#fff;border-radius:12px;padding:14px}.kpi small{display:block;color:#94a3b8}.kpi strong{font-size:23px}.row{display:flex;justify-content:space-between;gap:12px;align-items:center;border-top:1px solid #edf2f7;padding:11px 0}.row:first-of-type{border-top:0}.row span{display:flex;flex-direction:column;gap:2px}.row small{color:#64748b}.actions{display:flex;gap:7px;flex-wrap:wrap}.actions button{border:0;background:#e9eef5;color:#1e293b;font-weight:800;border-radius:8px;padding:8px 10px;cursor:pointer}.actions button:hover{background:#dce5ef}.danger{color:#b42318!important}.event{border-left:3px solid #94a3b8;padding-left:12px}.history{display:grid;gap:7px}.history div{background:#f8fafc;border-radius:9px;padding:10px;font-size:13px}.bar{height:7px;background:#e2e8f0;border-radius:9px;overflow:hidden}.bar i{display:block;height:100%;background:currentColor}.muted{color:#64748b}@media(max-width:700px){.grid{grid-template-columns:1fr}.row{align-items:flex-start;flex-direction:column}}''')
Path('src/app/coach-hub-view.tsx').write_text(r'''"use client";
import { useState } from "react";
import type { SeasonState } from "@/game-engine/season";
import { activeMedicalCases, playerMedicalRisk, type ReturnPlan } from "@/game-engine/medical";
import { pendingPlayerLifeEvents } from "@/game-engine/player-life";
import { financeProjection, monthlyWageSpend, type CoachFinanceRequestType } from "@/game-engine/coach-finance";
import styles from "./coach-hub-view.module.css";

type Tab="Médico"|"Vida do elenco"|"Torcida & estádio"|"Finanças"|"História";
const money=(v:number)=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0}).format(v),eur=(v:number)=>`€${(v/1_000_000).toLocaleString("pt-BR",{maximumFractionDigits:1})} mi`;
export default function CoachHubView({season,onMedical,onLife,onFinance}:{season:SeasonState;onMedical:(playerId:string,plan:ReturnPlan)=>void;onLife:(eventId:string,choiceId:string)=>void;onFinance:(type:CoachFinanceRequestType)=>void}){const[tab,setTab]=useState<Tab>("Médico"),club=season.league.clubs.find(c=>c.id===season.selectedClubId)??season.league.clubs[0],cases=activeMedicalCases(season.medical),life=pendingPlayerLifeEvents(season.playerLife),stadium=season.stadium,projection=financeProjection(club,stadium.seasonGateRevenueBrl,season.livingWorld.boardConfidence),wages=monthlyWageSpend(club);return <div className={styles.layout}><div className={styles.tabs}>{(["Médico","Vida do elenco","Torcida & estádio","Finanças","História"] as Tab[]).map(value=><button key={value} className={tab===value?styles.active:""} onClick={()=>setTab(value)}>{value}</button>)}</div>
{tab==="Médico"&&<><div className={styles.kpis}><div className={styles.kpi}><small>Casos ativos</small><strong>{cases.length}</strong></div><div className={styles.kpi}><small>Maior risco</small><strong>{Math.max(0,...club.players.map(p=>playerMedicalRisk(season.medical,p)))}%</strong></div><div className={styles.kpi}><small>Histórico</small><strong>{season.medical.history.length}</strong></div></div><div className={styles.grid}>{cases.length?cases.map(item=>{const p=club.players.find(p=>p.id===item.playerId);return <div className={styles.card} key={item.id}><h3>{item.playerName} • {item.kind}</h3><p>{item.severity} • {item.daysRemaining} dia(s) • risco de recaída {item.recurrenceRisk}%</p><div className={styles.bar}><i style={{width:`${item.recurrenceRisk}%`}}/></div><p>Plano atual: <b>{item.plan}</b>{item.recurrences?` • ${item.recurrences} ocorrência(s) anterior(es)`:""}</p><div className={styles.actions}>{(["Preservar","Retorno gradual","Liberar"] as ReturnPlan[]).map(plan=><button className={plan==="Liberar"?styles.danger:""} key={plan} onClick={()=>onMedical(item.playerId,plan)}>{plan}</button>)}</div>{p&&<small className={styles.muted}>Condição {p.condition}% • fadiga {p.fatigue}%</small>}</div>}):<div className={styles.card}><h3>Nenhum caso em tratamento</h3><p>A comissão segue monitorando fadiga, condição e histórico para calcular risco de recorrência.</p></div>}</div></>}
{tab==="Vida do elenco"&&<div className={styles.grid}>{life.length?life.map(event=><div className={`${styles.card} ${styles.event}`} key={event.id}><h3>{event.kind} • {event.playerName}</h3><p>{event.title}</p><p>{event.body}</p><div className={styles.actions}>{event.choices.map(choice=><button key={choice.id} onClick={()=>onLife(event.id,choice.id)}>{choice.label}</button>)}</div></div>):<div className={styles.card}><h3>Vestiário sem questões pessoais pendentes</h3><p>Eventos de família, adaptação, disciplina, vida social e empresários surgem de forma contextual ao longo dos dias.</p></div>}{season.playerLife.events.filter(e=>e.resolved).slice(0,8).map(event=><div className={styles.card} key={event.id}><h3>{event.playerName} • {event.kind}</h3><p>{event.title}</p><small className={styles.muted}>Resolvido em {event.date}</small></div>)}</div>}
{tab==="Torcida & estádio"&&<><div className={styles.kpis}><div className={styles.kpi}><small>Capacidade simulada</small><strong>{stadium.capacity.toLocaleString("pt-BR")}</strong></div><div className={styles.kpi}><small>Humor da torcida</small><strong>{stadium.fanMood}%</strong></div><div className={styles.kpi}><small>Renda da temporada</small><strong>{money(stadium.seasonGateRevenueBrl)}</strong></div></div><div className={styles.grid}><div className={styles.card}><h3>Arquibancada & organizadas</h3><p>Humor geral {stadium.fanMood}% • organizadas {stadium.organizedMood}% • ingresso médio {money(stadium.ticketPriceBrl)}.</p><p>Público acumulado: <b>{stadium.seasonAttendance.toLocaleString("pt-BR")}</b>.</p></div>{stadium.events.slice(0,8).map(event=><div className={styles.card} key={event.id}><h3>{event.kind}</h3><p>{event.title}</p><p>{event.body}</p><small>{event.date}</small></div>)}{stadium.matchdays.slice(0,6).map(item=><div className={styles.card} key={item.id}><h3>{item.competition} • {item.opponent}</h3><p>{item.goalsFor} × {item.goalsAgainst}{item.rivalry?` • ${item.rivalry}`:""}</p><small>{item.home?`${item.attendance.toLocaleString("pt-BR")} presentes • ${money(item.gateRevenueBrl)}`:"Jogo fora"}</small></div>)}</div></>}
{tab==="Finanças"&&<><div className={styles.kpis}><div className={styles.kpi}><small>Projeção da diretoria</small><strong>{projection}</strong></div><div className={styles.kpi}><small>Verba de transferências</small><strong>{eur(club.transferBudgetEur)}</strong></div><div className={styles.kpi}><small>Folha / teto</small><strong>{Math.round(wages/Math.max(1,club.wageBudgetBrlMonthly)*100)}%</strong></div></div><div className={styles.card}><h3>O treinador solicita. A diretoria decide.</h3><p>Você não controla o caixa do clube: pode defender prioridades esportivas, e a resposta considera confiança, segurança no cargo, reputação e projeção financeira.</p><div className={styles.actions}>{(["Verba extra","Contratação prioritária","Melhoria de estrutura","Renovação acima do teto"] as CoachFinanceRequestType[]).map(type=><button key={type} onClick={()=>onFinance(type)}>{type}</button>)}</div></div><div className={styles.history}>{season.coachFinance.requests.slice(0,10).map(request=><div key={request.id}><b>{request.approved?"APROVADO":"NEGADO"} • {request.type}</b><br/>{request.message}</div>)}</div></>}
{tab==="História"&&<><div className={styles.kpis}><div className={styles.kpi}><small>Temporadas arquivadas</small><strong>{season.legacy.seasons.length}</strong></div><div className={styles.kpi}><small>Aposentadorias</small><strong>{season.legacy.retirements.length}</strong></div><div className={styles.kpi}><small>Novos jogadores</small><strong>{season.legacy.generatedPlayers}</strong></div></div><div className={styles.grid}>{season.legacy.seasons.slice(0,12).map(item=><div className={styles.card} key={`${item.year}-${item.competitionId}`}><h3>{item.year} • {item.leagueChampion}</h3><p>Artilheiro: {item.topScorer} ({item.topScorerGoals}) • recorde de pontos {item.highestPoints}</p><p>Maior vitória: {item.biggestWin}</p><small>{item.cupChampions.map(c=>`${c.competition}: ${c.champion}`).join(" • ")||"Sem copas arquivadas"}</small></div>)}{!season.legacy.seasons.length&&<div className={styles.card}><h3>A história começa nesta temporada</h3><p>Ao virar o ano, campeões, artilheiros, recordes, transferências, técnicos e títulos entram no arquivo permanente do mundo.</p></div>}{season.legacy.retirements.slice(0,8).map(item=><div className={styles.card} key={`${item.id}-${item.year}`}><h3>Aposentadoria • {item.name}</h3><p>{item.clubName} • {item.age} anos • {item.year}</p></div>)}</div></>}
</div>}
''')

Path('src/app/season-calendar-view.tsx').write_text(r'''import type { SeasonState } from "@/game-engine/season";import { userWorldCompetitionMatches } from "@/game-engine/world-competitions";import styles from "./coach-hub-view.module.css";
const date=(iso?:string)=>iso?new Date(`${iso}T12:00:00`).toLocaleDateString("pt-BR",{day:"2-digit",month:"short"}):"—";
export default function SeasonCalendarView({season}:{season:SeasonState}){const club=season.league.clubs.find(c=>c.id===season.selectedClubId)!,league=season.league.fixtures.filter(f=>f.homeClubId===club.id||f.awayClubId===club.id).map(f=>({id:f.id,date:f.date??"",competition:season.league.competitionName??"Liga",stage:`Rodada ${f.round}`,opponent:season.league.clubs.find(c=>c.id===(f.homeClubId===club.id?f.awayClubId:f.homeClubId))?.name??"—",home:f.homeClubId===club.id,played:f.played,score:f.played?`${f.homeClubId===club.id?f.homeGoals:f.awayGoals} × ${f.homeClubId===club.id?f.awayGoals:f.homeGoals}`:"—"})),cups=userWorldCompetitionMatches(season.worldCompetitions,club.id).map(({tournament,match})=>({id:match.id,date:match.date,competition:tournament.definition.name,stage:match.stage,opponent:match.home.activeClubId===club.id?match.away.name:match.home.name,home:match.home.activeClubId===club.id,played:match.played,score:match.played?`${match.home.activeClubId===club.id?match.homeGoals:match.awayGoals} × ${match.home.activeClubId===club.id?match.awayGoals:match.homeGoals}${match.shootoutHome!==undefined?" (pên.)":""}`:"—"})),items=[...league,...cups].sort((a,b)=>a.date.localeCompare(b.date));return <div className={styles.layout}><div className={styles.card}><h3>Calendário integrado • liga + copas</h3><p>As partidas de mata-mata ocupam datas reais do calendário do treinador. Sequências curtas entre jogos reduzem o tempo de recuperação e tornam rotação e departamento médico mais importantes.</p>{items.map(item=><div className={styles.row} key={item.id}><span><b>{date(item.date)} • {item.competition}</b><small>{item.stage} • {item.home?"Casa":"Fora"} • {item.opponent}</small></span><b>{item.played?item.score:item.date===season.currentDate?"HOJE":"Agendado"}</b></div>)}</div></div>}
''')

