pattern=r'  function handlePlay\(\)\{.*?\n  \}\n  function handleLiveChange'
new_handle=r'''  function handlePlay(){
    if(!employed){flash("Você precisa assumir um clube antes de voltar ao banco de reservas.");return}if(!matchdaySelectionReady(season)){flash(`Complete a convocação: 11 titulares e o banco permitido pela ${competition.shortName}.`);return}const context=getTodayUserMatchContext(season);if(!context){const next=getNextUserMatchContext(season);flash(next?`A próxima partida é ${next.competitionName} em ${formatDate(next.date)}. Avance os dias até o jogo.`:"Não há partida pendente no calendário.");return}const opponent=context.userSide==="home"?context.away:context.home,aiTactic=opponent.id.startsWith("club-")?tacticForClub(season.clubAi,opponent.id):DEFAULT_TACTIC,session=createLiveMatch(context.home,context.away,`${season.baseSeed}:${season.year}:${context.matchId}:live`,context.userSide,season.lineupIds,tactic,season.benchIds,competition.benchSize,competition.maxSubstitutions,aiTactic);setMatch(null);setMatchClubs({home:context.home,away:context.away});setLiveMatch(session);
  }
  function handleLiveChange'''
s,count=re.subn(pattern,new_handle,s,flags=re.S)
if count!=1: raise SystemExit(f'handlePlay patch count {count}')
old_finish='function handleLiveFinish(session:LiveMatchState){const result=liveMatchResult(session);if(!result)return;const participants=session.usedPlayerIds.filter(id=>club.players.some(p=>p.id===id)),next=playCurrentRound(season,tactic,result,participants);persist(next);setLiveMatch(null);setMatch(result)}'
new_finish='function handleLiveFinish(session:LiveMatchState){const result=liveMatchResult(session);if(!result)return;const participants=session.usedPlayerIds.filter(id=>club.players.some(p=>p.id===id)),context=getTodayUserMatchContext(season),next=context?.kind==="Copa"?playUserWorldCompetitionMatch(season,context.matchId,tactic,result,participants):playCurrentRound(season,tactic,result,participants);persist(next);setLiveMatch(null);setMatch(result)}'
if old_finish not in s: raise SystemExit('finish marker missing')
s=s.replace(old_finish,new_finish)
s=s.replace('setMatch(null);setLiveMatch(null);setTactic(DEFAULT_TACTIC);flash(`Temporada', 'setMatch(null);setLiveMatch(null);setMatchClubs(null);setTactic(DEFAULT_TACTIC);flash(`Temporada')
s=s.replace('const matchHome=season.lastUserMatch?league.clubs.find(c=>c.id===season.lastUserMatch?.homeClubId):undefined,matchAway=season.lastUserMatch?league.clubs.find(c=>c.id===season.lastUserMatch?.awayClubId):undefined,liveHome=currentFixture?league.clubs.find(c=>c.id===currentFixture.homeClubId):undefined,liveAway=currentFixture?league.clubs.find(c=>c.id===currentFixture.awayClubId):undefined;', 'const matchHome=matchClubs?.home??(season.lastUserMatch?league.clubs.find(c=>c.id===season.lastUserMatch?.homeClubId):undefined),matchAway=matchClubs?.away??(season.lastUserMatch?league.clubs.find(c=>c.id===season.lastUserMatch?.awayClubId):undefined),liveHome=matchClubs?.home,liveAway=matchClubs?.away;')
s=s.replace('active==="Clube"?<ClubManagementView season={season}', 'active==="Centro do Treinador"?<CoachHubView season={season} onMedical={handleMedical} onLife={handleLife} onFinance={handleFinance}/>:\n        active==="Clube"?<ClubManagementView season={season}')
s=s.replace('active==="Calendário"?<CalendarView season={season}/>', 'active==="Calendário"?<SeasonCalendarView season={season}/>')
s=s.replace('opponent?<TacticsView club={club} opponent={opponent}', 'opponent?<TacticsView club={club} opponent={opponent}')
s=s.replace('onContinue={()=>{setMatch(null);setActive("Visão geral")}}', 'onContinue={()=>{setMatch(null);setMatchClubs(null);setActive("Visão geral")}}')
# Next-match card must keep league opponent rather than potentially cup opponent.
s=s.replace('currentFixture&&opponent&&<NextMatchCard fixture={currentFixture} club={club} opponent={opponent}', 'currentFixture&&leagueOpponent&&<NextMatchCard fixture={currentFixture} club={club} opponent={leagueOpponent}')
# Welcome sentence points at true next match.
s=s.replace('`${opponent?`Próximo adversário: ${opponent.name}.`:"Sem partida pendente"}', '`${nextMatchContext?`Próximo jogo: ${nextMatchContext.competitionName} contra ${opponent?.name} em ${formatDate(nextMatchContext.date)}.`:"Sem partida pendente"}')
p.write_text(s)

# ---------- Tests ----------
Path('src/game-engine/mega-sprints.test.ts').write_text(r'''import{describe,expect,it}from"vitest";import{createLeague}from"./league";import{advanceLiveMatchMinute,createLiveMatch,liveMatchResult,makeSubstitution,requiredUserSubstitutions,resumeSecondHalf,startLiveMatch}from"./live-match";import{DEFAULT_TACTIC,simulateMatch}from"./match";import{createMedicalState,medicalAfterMatch,applyMedicalReturnPlan}from"./medical";import{createPlayerLifeState,processPlayerLifeDay,resolvePlayerLifeEvent}from"./player-life";import{createStadiumState,stadiumAfterMatch,rivalryInfo}from"./stadium";import{createCoachFinanceState,resolveCoachFinanceRequest}from"./coach-finance";import{archiveWorldSeason,createWorldLegacy,retireAndRegenerate}from"./legacy";import{createWorldCompetitions,completeWorldCompetitionMatch,userWorldCompetitionMatches}from"./world-competitions";import{createClubAiState}from"./club-ai";import{createInternationalMarket}from"./international-market";
describe("mega sprints 20/21/23/24/28/29 + competitions 2.0",()=>{const league=createLeague("mega",2026,"BRA1"),club=league.clubs[0],opp=league.clubs[1];it("motor 2.0 produz métricas avançadas e mapa de chutes",()=>{const r=simulateMatch(club,opp,"advanced");expect(r.xgHome).toBeGreaterThanOrEqual(0);expect(r.passesHome).toBeGreaterThan(100);expect(r.shotMap?.length).toBe(r.shotsHome+r.shotsAway);expect(r.attackZonesHome).toBeTruthy()});it("partida ao vivo preserva superioridade numérica e IA de banco",()=>{const lineup=club.players.slice(0,11).map(p=>p.id);let found=false;for(let seed=0;seed<80&&!found;seed++){let state=startLiveMatch(createLiveMatch(club,opp,`red-${seed}`,"home",lineup,DEFAULT_TACTIC),club);while(state.phase!=="fulltime"){for(const id of requiredUserSubstitutions(state)){const incoming=state.homeBenchIds[0];if(incoming)state=makeSubstitution(state,"home",id,incoming)}if(state.phase==="halftime")state=resumeSecondHalf(state);else state=advanceLiveMatchMinute(state,club,opp)}const result=liveMatchResult(state)!;expect(result.passesHome).toBeGreaterThan(0);if(result.events.some(e=>e.type==="red_card")){found=true;expect(state.sentOffPlayerIds.length).toBeGreaterThan(0)}}expect(found).toBe(true)});it("médico calcula recorrência e permite retorno controlado",()=>{const p=club.players[0],result=simulateMatch(club,opp,"med");result.events.push({minute:20,type:"injury",team:"home",playerId:p.id,text:"teste"});p.injuryDays=8;let state=medicalAfterMatch(createMedicalState(),club,result,"2026-04-10","med");expect(state.cases[0].recurrenceRisk).toBeGreaterThan(0);const before=state.cases[0].recurrenceRisk,state2=applyMedicalReturnPlan(state,club,p.id,"Retorno gradual").state;expect(state2.cases[0].recurrenceRisk).toBeLessThan(before)});it("vida do jogador gera e resolve situações persistentes",()=>{let state=createPlayerLifeState(club,"life"),event;for(let d=1;d<160&&!event;d++){const date=`2026-${String(1+Math.floor((d-1)/28)).padStart(2,"0")}-${String(1+(d-1)%28).padStart(2,"0")}`;state=processPlayerLifeDay(state,club,date,"life");event=state.events.find(e=>!e.resolved)}expect(event).toBeTruthy();if(event){const result=resolvePlayerLifeEvent(state,club,event.id,event.choices[0].id,"life");expect(result.state.events.find(e=>e.id===event!.id)?.resolved).toBe(true)}});it("estádio reconhece clássico, público e renda",()=>{const pal=league.clubs.find(c=>c.name.toLowerCase().includes("palmeiras")),cor=league.clubs.find(c=>c.name.toLowerCase().includes("corinthians"));if(!pal||!cor)return;expect(rivalryInfo(pal.name,cor.name).weight).toBeGreaterThan(90);const r=simulateMatch(pal,cor,"derby"),st=stadiumAfterMatch(createStadiumState(pal),pal,cor,r,true,"Brasileirão","2026-05-01",75,"derby");expect(st.matchdays[0].attendance).toBeGreaterThan(0);expect(st.seasonGateRevenueBrl).toBeGreaterThan(0)});it("diretoria financeira decide pedidos do treinador",()=>{let approved=false;for(let i=0;i<80&&!approved;i++){const cloned={...club,players:club.players.map(p=>({...p,contract:{...p.contract}}))},res=resolveCoachFinanceRequest(createCoachFinanceState(2026),cloned,"Verba extra",10,90,90,90,`fin-${i}`);approved=res.state.requests[0]?.approved??false}expect(approved).toBe(true)});it("competições 2.0 têm data e aceitam resultado jogado",()=>{const world=createWorldCompetitions("BRA1",league,2026,"cups2"),user=league.clubs[0],games=userWorldCompetitionMatches(world,user.id);expect(games.length).toBeGreaterThan(0);expect(games[0].match.date).toMatch(/^2026-/);const r=simulateMatch(user,league.clubs[1],"cup-live"),next=completeWorldCompetitionMatch(world,games[0].match.id,r,"cup-live");expect(next.tournaments.flatMap(t=>t.matches).find(m=>m.id===games[0].match.id)?.played).toBe(true)});it("legado arquiva temporada, aposentadorias e regens",()=>{const world=createWorldCompetitions("BRA1",league,2026,"legacy"),ai=createClubAiState(league,"legacy"),market=createInternationalMarket(),legacy=archiveWorldSeason(createWorldLegacy(),league,world,ai,market,2026,"BRA1",league.clubs[0].id);expect(legacy.seasons).toHaveLength(1);const veteran=league.clubs[0].players[0];veteran.age=41;const result=retireAndRegenerate(legacy,league,2027,"legacy");expect(result.legacy.retirements.some(r=>r.id===veteran.id)).toBe(true);expect(result.legacy.generatedPlayers).toBeGreaterThan(0)})});
''')

